const ChevronDownIcon: Icon = /* @__PURE__ */ createIcon("chevron-down", iconNode2)

function ToolCodePreview({
  code,
  startLine = 1,
  maxLines,
  highlight,
  label,
  className,
  ...props
}: ToolCodePreviewProps) {
  const all = code.replace(/\n$/, "").split("\n")
  const foldable = maxLines !== undefined && all.length > maxLines + 3
  const head = foldable ? all.slice(0, maxLines) : all
  const tail = foldable ? all.slice(maxLines) : []
  const width = String(startLine + all.length - 1).length

  // The folded lines mount on the first "Show more", then grow from 0fr to 1fr in the next frame,
  // so a long file costs nothing until someone asks for it and the height never jumps.
  const [mounted, setMounted] = React.useState(false)
  const [open, setOpen] = React.useState(false)
  const toggle = () => {
    if (open) return setOpen(false)
    if (mounted) return setOpen(true)
    setMounted(true)
    requestAnimationFrame(() => requestAnimationFrame(() => setOpen(true)))
  }

  return (
    <div
      data-slot="tool-code-preview"
      data-state={foldable ? (open ? "open" : "closed") : undefined}
      className={cn("rounded-(--chatcn-radius-md) bg-(color:--chatcn-inset) min-w-0 overflow-hidden", className)}
      {...props}
    >
      {label ? (
        <div className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) px-3 pt-2 font-medium">{label}</div>
      ) : null}
      {/* biome-ignore lint/a11y/useSemanticElements: a labelled scroll region, not a form fieldset */}
      <div
        // biome-ignore lint/a11y/noNoninteractiveTabindex: scrollable regions must be reachable by keyboard
        tabIndex={0}
        role="group"
        aria-label="File contents"
        className={cn(
          "rounded-(--chatcn-radius-md) focus-visible:outline-(color:--chatcn-accent) chatcn-scroll max-h-72 overflow-auto pt-2 outline-none focus-visible:outline-2 focus-visible:-outline-offset-2",
          foldable ? "pb-0" : "pb-2",
        )}
      >
        <pre
          className={cn(
            "text-[0.75rem]/[1rem] relative w-max min-w-full font-mono leading-5",
            // The last three visible lines fade out: a measured hint that the file goes on. A mask,
            // so it works on any surface and never paints a gradient.
            foldable &&
              !open &&
              "[mask-image:linear-gradient(to_bottom,black_calc(100%-3.75rem),transparent)]",
          )}
        >
          <code className="grid">
            <CodeLines lines={head} first={startLine} width={width} highlight={highlight} />
            {mounted ? (
              <span
                data-slot="tool-code-preview-fold"
                className={cn(
                  "ease-(--chatcn-ease-out) grid transition-[grid-template-rows] duration-200 motion-reduce:transition-none",
                  open ? "grid-rows-[1fr]" : "grid-rows-[0fr]",
                )}
              >
                <span className="grid min-h-0 overflow-hidden" inert={!open}>
                  <CodeLines
                    lines={tail}
                    first={startLine + head.length}
                    width={width}
                    highlight={highlight}
                  />
                </span>
              </span>
            ) : null}
          </code>
        </pre>
      </div>
      {foldable ? (
        <div className="flex px-1 py-1.5">
          <Button
            size="xs"
            aria-expanded={open}
            onClick={toggle}
            className="text-(color:--chatcn-fg-muted) hover:text-(color:--chatcn-fg) gap-1 tabular-nums"
          >
            {open
              ? "Show fewer lines"
              : `Show ${tail.length} more ${tail.length === 1 ? "line" : "lines"}`}
            <ChevronDownIcon
              className={cn(
                "ease-(--chatcn-ease-out) transition-transform duration-200 motion-reduce:transition-none",
                open && "rotate-180",
              )}
            />
          </Button>
        </div>
      ) : null}
    </div>
  )
}

function humanize(name: string) {
  const words = name
    .replace(/^tool-/, "")
    .replace(/[_-]+/g, " ")
    .trim()
  return words.charAt(0).toUpperCase() + words.slice(1)
}

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

const RUNNING2: ToolDisplayState[] = ["input-streaming", "input-available", "approval-responded"]

function isRunning(state: ToolDisplayState, decision?: ToolCallProps["decision"]) {
  if (state === "approval-responded" && decision?.approved === false) return false
  return RUNNING2.includes(state)
}

/** Measures run time itself when the caller passes no timing, so durations show up for free. */
function useAutoTiming(running: boolean, done: boolean) {
  const [startedAt, setStartedAt] = React.useState<number>()
  const [durationMs, setDurationMs] = React.useState<number>()
  React.useEffect(() => {
    if (running && startedAt === undefined) setStartedAt(Date.now())
    if (done && startedAt !== undefined && durationMs === undefined)
      setDurationMs(Date.now() - startedAt)
  }, [running, done, startedAt, durationMs])
  return { startedAt, durationMs }
}

function useElapsed(startedAt: number | undefined, active: boolean) {
  // Starts empty and reads the clock after mount: a render must not read it (Next.js prerender).
  const [now, setNow] = React.useState<number | null>(null)
  React.useEffect(() => {
    if (!active || startedAt === undefined) return
    setNow(Date.now())
    // Ticks once per second: a counter that changes faster only adds noise.
    const id = window.setInterval(() => setNow(Date.now()), 1000)
    return () => window.clearInterval(id)
  }, [active, startedAt])
  if (!active || startedAt === undefined) return undefined
  return Math.max(0, (now ?? startedAt) - startedAt)
}

/**
 * Tolerant JSON parser for streaming tool input.
 *
 * Parses as much of a truncated JSON document as possible: unterminated strings keep their text,
 * open objects and arrays are closed, partial literals (`tr`, `nul`) are completed, partial numbers
 * (`12.`, `3e`) are trimmed and trailing commas are ignored. Keys without a value are dropped.
 * Single pass, no eval, no dependencies.
 */

/** Result of `parsePartialJson`. */
interface PartialJsonResult {
  /** Best-effort value, `undefined` when nothing could be parsed yet. */
  value: unknown
  /** True when the text held one finished JSON value (trailing commas tolerated). */
  complete: boolean
}

const NONE = Symbol("none")

type Parsed = unknown | typeof NONE

const LITERALS: Record<string, [string, unknown]> = {
  t: ["true", true],
  f: ["false", false],
  n: ["null", null],
}

const ESCAPES: Record<string, string> = {
  '"': '"',
  "\\": "\\",
  "/": "/",
  b: "\b",
  f: "\f",
  n: "\n",
  r: "\r",
  t: "\t",
}

const NUMBER_CHAR = /[-+.eE0-9]/

class Parser {
  i = 0
  /** Set when input ran out or a syntax error was hit; unwinds every open container. */
  stopped = false

  readonly s: string

  constructor(s: string) {
    this.s = s
  }

  ws(): void {
    const s = this.s
    while (this.i < s.length) {
      const c = s.charCodeAt(this.i)
      if (c !== 32 && c !== 10 && c !== 13 && c !== 9) return
      this.i++
    }
  }

  value(): Parsed {
    this.ws()
    const c = this.s[this.i]
    if (c === undefined) return this.stop()
    if (c === "{") return this.object()
    if (c === "[") return this.array()
    if (c === '"') return this.string()
    if (c === "-" || (c >= "0" && c <= "9")) return this.number()
    if (c in LITERALS) return this.literal(c)
    return this.stop()
  }

  stop(): typeof NONE {
    this.stopped = true
    return NONE
  }

  object(): Record<string, unknown> {
    const obj: Record<string, unknown> = {}
    this.i++
    while (true) {
      this.ws()
      const c = this.s[this.i]
      if (c === "}") {
        this.i++
        return obj
      }
      if (c === ",") {
        this.i++
        continue
      }
      if (c !== '"') {
        this.stop()
        return obj
      }
      const key = this.string()
      if (this.stopped) return obj
      this.ws()
      if (this.s[this.i] !== ":") {
        this.stop()
        return obj
      }
      this.i++
      const v = this.value()
      if (v !== NONE) {
        // defineProperty keeps a "__proto__" key from replacing the prototype.
        Object.defineProperty(obj, key, {
          value: v,
          enumerable: true,
          writable: true,
          configurable: true,
        })
      }
      if (this.stopped) return obj
      this.ws()
      const next = this.s[this.i]
      if (next === ",") this.i++
      else if (next !== "}") {
        this.stop()
        return obj
      }
    }
  }

  array(): unknown[] {
    const arr: unknown[] = []
    this.i++
    while (true) {
      this.ws()
      const c = this.s[this.i]
      if (c === "]") {
        this.i++
        return arr
      }
      if (c === ",") {
        this.i++
        continue
      }
      const v = this.value()
      if (v !== NONE) arr.push(v)
      if (this.stopped) return arr
      this.ws()
      const next = this.s[this.i]
      if (next === ",") this.i++
      else if (next !== "]") {
        this.stop()
        return arr
      }
    }
  }

  string(): string {
    const s = this.s
    let out = ""
    let start = ++this.i
    while (this.i < s.length) {
      const c = s[this.i]
      if (c === '"') {
        out += s.slice(start, this.i++)
        return out
      }
      if (c !== "\\") {
        this.i++
        continue
      }
      out += s.slice(start, this.i)
      start = this.i
      const e = s[this.i + 1]
      if (e === undefined) break
      if (e === "u") {
        const hex = s.slice(this.i + 2, this.i + 6)
        if (hex.length < 4) break
        const code = Number.parseInt(hex, 16)
        out += Number.isNaN(code) ? hex : String.fromCharCode(code)
        this.i += 6
      } else {
        out += ESCAPES[e] ?? e
        this.i += 2
      }
      start = this.i
    }
    // Ran out of input inside the string. A partial escape (start sits on it) is dropped.
    if (s[start] !== "\\") out += s.slice(start)
    this.stopped = true
    const last = out.charCodeAt(out.length - 1)
    return last >= 0xd800 && last <= 0xdbff ? out.slice(0, -1) : out
  }

  number(): Parsed {
    const s = this.s
    const start = this.i
    while (this.i < s.length && NUMBER_CHAR.test(s[this.i] as string)) this.i++
    const token = s.slice(start, this.i)
    // Trim a dangling sign, dot or exponent left by truncation (`12.`, `3e`, `-`).
    const trimmed = token.replace(/[-+.eE]+$/, "")
    if (trimmed !== token) this.stopped = true
    const n = Number(trimmed)
    return trimmed === "" || Number.isNaN(n) ? this.stop() : n
  }

  literal(first: string): Parsed {
    const [word, value] = LITERALS[first] as [string, unknown]
    const rest = this.s.slice(this.i, this.i + word.length)
    if (rest === word) {
      this.i += word.length
      return value
    }
    if (this.i + rest.length === this.s.length && word.startsWith(rest)) {
      this.i += rest.length
      this.stopped = true
      return value
    }
    return this.stop()
  }
}

/** Parse possibly truncated JSON, returning the best-effort value and whether it was complete. */
function parsePartialJson(text: string): PartialJsonResult {
  const p = new Parser(text)
  const v = p.value()
  if (!p.stopped) p.ws()
  return { value: v === NONE ? undefined : v, complete: !p.stopped && p.i === text.length }
}

const NBSP = "\u00a0"

/** A minute and up: "4 m 12 s", then "2 h 5 m", then "3 d 4 h", never "1 m 60 s". */
function formatLong(seconds: number) {
  const t = Math.round(seconds)
  if (t < 3600) return `${Math.floor(t / 60)}${NBSP}m ${t % 60}${NBSP}s`
  const h = Math.floor(t / 3600)
  if (h < 24) return `${h}${NBSP}h ${Math.floor((t % 3600) / 60)}${NBSP}m`
  return `${Math.floor(h / 24)}${NBSP}d ${h % 24}${NBSP}h`
}

/**
 * Final durations keep a decimal under 10 s. Live counters (`precise: false`) tick in whole
 * seconds, so the figure turns over once a second and never shows a frozen ".0".
 */
function formatDuration(ms: number, precise = true) {
  if (precise && ms < 1000) return `${Math.max(1, Math.round(ms))}${NBSP}ms`
  const s = ms / 1000
  if (precise && s < 10) return `${s.toFixed(1)}${NBSP}s`
  if (s < 60) return `${precise ? Math.round(s) : Math.floor(s)}${NBSP}s`
  return formatLong(precise ? s : Math.floor(s))
}

function statusLabel(props: {
  state: ToolDisplayState
  decision?: ToolCallProps["decision"]
  durationMs?: number
  elapsed?: number
}) {
  const { state, decision, durationMs, elapsed } = props
  switch (state) {
    case "input-streaming":
    case "input-available":
      return elapsed !== undefined && elapsed >= 1000 ? formatDuration(elapsed, false) : "Running"
    case "approval-requested":
      return "Needs approval"
    case "approval-responded":
      if (decision?.approved === false) return "Denied"
      return elapsed !== undefined && elapsed >= 1000 ? formatDuration(elapsed, false) : "Running"
    case "output-available":
      return durationMs !== undefined ? formatDuration(durationMs) : "Done"
    case "output-error":
      return "Failed"
    case "output-denied":
      return "Denied"
    case "cancelled":
      return "Cancelled"
  }
}

const DETAIL_KEYS = [
  "path",
  "file",
  "filePath",
  "query",
  "command",
  "cmd",
  "url",
  "pattern",
  "name",
]

function detailFrom(input: unknown): string | undefined {
  if (!input || typeof input !== "object") return undefined
  for (const key of DETAIL_KEYS) {
    const value = (input as Record<string, unknown>)[key]
    if (typeof value === "string" && value.length > 0) return value
  }
  return undefined
}

