let context: CanvasRenderingContext2D | null | undefined

/** A text measurer that matches an element's font, from one shared canvas. */
function measurerFor(element: HTMLElement) {
  if (context === undefined) context = document.createElement("canvas").getContext("2d")
  const ctx = context
  if (!ctx) return null
  const style = getComputedStyle(element)
  const spacing = Number.parseFloat(style.letterSpacing) || 0
  const font = `${style.fontStyle} ${style.fontWeight} ${style.fontSize} ${style.fontFamily}`
  return {
    spacing,
    measure: (value: string) => {
      ctx.font = font
      if ("letterSpacing" in ctx) ctx.letterSpacing = `${spacing}px`
      return ctx.measureText(value).width
    },
  }
}

/**
 * Splits a file name into its stem and extension (with the dot). Dotfiles, and names whose last
 * "extension" is really a sentence (`notes v2. final`), keep everything in the stem.
 */
function splitChatcnFileName(name: string): { stem: string; ext: string } {
  const dot = name.lastIndexOf(".")
  if (dot <= 0 || name.length - dot > 10 || /\s/.test(name.slice(dot))) {
    return { stem: name, ext: "" }
  }
  return { stem: name.slice(0, dot), ext: name.slice(dot) }
}

/**
 * The end of the stem worth keeping beside the extension: the last word when it is short
 * (`2026` in `quarterly-report-2026.pdf`), else the last four characters.
 */
function stemTail(stem: string) {
  const word = /[\s\-_.]([^\s\-_.]{2,8})$/.exec(stem)?.[1]
  const tail = word ?? stem.slice(-4).replace(/^[\s\-_.]+/, "")
  return stem.length - tail.length >= 4 ? tail : ""
}

const SEPARATORS = /[\s\-_.]+$/

const ELLIPSIS = "…"

/**
 * Truncates `text` in the middle so it fits `maxWidth`, as one string, so the ellipsis sits flush
 * against both halves: `quarterly-rep…2026.pdf`. The extension is never cut. `measure` returns
 * the rendered width of a string. Exported for tests and for canvas or SVG labels.
 */
function middleTruncateChatcn(
  text: string,
  maxWidth: number,
  measure: (value: string) => number,
): string {
  if (maxWidth <= 0 || measure(text) <= maxWidth) return text
  const { stem, ext } = splitChatcnFileName(text)
  const keep = stemTail(stem)
  // Prefer a tail that tells similar files apart; drop to the bare extension when room is short.
  const tails = keep ? [keep + ext, ext] : [ext]
  for (const [index, tail] of tails.entries()) {
    const headMax = text.length - tail.length
    const minHead = index < tails.length - 1 ? Math.min(6, headMax) : 1
    const join = (n: number) => {
      const head = text.slice(0, n)
      return (head.replace(SEPARATORS, "") || head) + ELLIPSIS + tail
    }
    let lo = 0
    let hi = headMax
    while (lo < hi) {
      const mid = Math.ceil((lo + hi) / 2)
      if (measure(join(mid)) <= maxWidth) lo = mid
      else hi = mid - 1
    }
    if (lo >= minHead) return join(lo)
  }
  return ELLIPSIS + ext
}

const useIsoLayoutEffect = typeof window === "undefined" ? React.useEffect : React.useLayoutEffect

/**
 * Middle truncation that reflows with its container. Render it like this, so the name keeps its
 * full width as the element's natural size (chips still hug long names) and screen readers hear
 * the whole name, while the eye sees the shortened one:
 *
 * ```tsx
 * const name = useChatcnMiddleTruncate(file.name)
 * <span ref={name.ref} title={name.title} className="block min-w-0 overflow-hidden whitespace-nowrap">
 *   <span ref={name.textRef} style={name.textStyle} aria-hidden="true" dir="auto">{name.text}</span>
 *   <span dir="auto" className="block h-0 overflow-hidden">{file.name}</span>
 * </span>
 * ```
 *
 * Measures with a canvas once per width change (a ResizeObserver feeds the width, so there is
 * no layout read in the loop), then checks the rendered line once and corrects a sub-pixel
 * overshoot. The part of a glyph that no longer fits is spread as tracking too small to see
 * (at most 0.4 px a glyph), so a shortened name ends exactly at its box and whatever sits beside
 * it keeps the same gap as beside a full name. Pass `textStyle` to the visible span for that.
 * Works in either direction: the text keeps its own direction through `dir="auto"`.
 */
function useChatcnMiddleTruncate(value: string) {
  const ref = React.useRef<HTMLSpanElement>(null)
  const textRef = React.useRef<HTMLSpanElement>(null)
  const [fit, setFit] = React.useState<{ source: string; text: string; tracking?: string }>({
    source: value,
    text: value,
  })
  const width = React.useRef(-1)
  const corrections = React.useRef(0)

  const run = React.useCallback(
    (available: number) => {
      const element = ref.current
      if (!element || available <= 0) return
      width.current = available
      const measurer = measurerFor(element)
      if (!measurer) return
      const text = middleTruncateChatcn(value, available, measurer.measure)
      let tracking: string | undefined
      if (text !== value) {
        const slack = available - measurer.measure(text) - 0.5
        const extra = Math.min(Math.max(slack / Array.from(text).length, 0), 0.4)
        if (extra > 0.01) tracking = `${(measurer.spacing + extra).toFixed(3)}px`
      }
      setFit((current) =>
        current.source === value && current.text === text && current.tracking === tracking
          ? current
          : { source: value, text, tracking },
      )
    },
    [value],
  )

  useIsoLayoutEffect(() => {
    const element = ref.current
    if (!element) return
    corrections.current = 0
    run(element.getBoundingClientRect().width)
    const observer = new ResizeObserver(([entry]) => {
      const next = entry?.contentRect.width ?? 0
      if (Math.abs(next - width.current) < 0.5) return
      corrections.current = 0
      run(next)
    })
    observer.observe(element)
    // Webfonts change every width: measure again once they are in.
    let live = true
    if (document.fonts && document.fonts.status !== "loaded") {
      document.fonts.ready.then(() => {
        if (live && ref.current) run(ref.current.getBoundingClientRect().width)
      })
    }
    return () => {
      live = false
      observer.disconnect()
    }
  }, [run])

  // Canvas and layout can disagree by a fraction of a pixel (kerning, tabular figures): one check
  // per fit, and at most two corrections, so it never loops.
  useIsoLayoutEffect(() => {
    const element = ref.current
    const line = textRef.current
    if (!element || !line || fit.text === value || corrections.current >= 2) return
    const over = line.getBoundingClientRect().width - element.getBoundingClientRect().width
    if (over > 0.25) {
      corrections.current += 1
      const real = width.current
      run(real - over - 0.5)
      width.current = real
    }
  }, [fit, value, run])

  const fresh = fit.source === value
  const text = fresh ? fit.text : value
  const truncated = text !== value
  const textStyle: React.CSSProperties | undefined =
    fresh && fit.tracking ? { letterSpacing: fit.tracking } : undefined
  return { ref, textRef, text, textStyle, truncated, title: truncated ? value : undefined }
}

/** The file name part: cut in the middle when it alone is too wide, so the extension stays. */
function ToolPathName({ name }: { name: string }) {
  const fit = useChatcnMiddleTruncate(name)
  return (
    <span
      ref={fit.ref}
      className="block max-w-full min-w-0 shrink-0 overflow-hidden whitespace-nowrap"
    >
      <span ref={fit.textRef} style={fit.textStyle} aria-hidden="true">
        {fit.text}
      </span>
      <span className="block h-0 overflow-hidden">{name}</span>
    </span>
  )
}

/**
 * A path or URL that gives way from the folders, never the file name:
 * `prisma/migrations/2026…/migration.sql`. The directory shrinks first and the name only when it
 * alone is wider than the row. The full path is in `title`.
 */
function ToolPath({ path, className }: { path: string; className?: string }) {
  const cut = path.replace(/\/+$/, "").lastIndexOf("/")
  const dir = cut > 0 ? path.slice(0, cut + 1) : ""
  const base = cut > 0 ? path.slice(cut + 1) : path
  return (
    <span data-slot="tool-path" title={path} className={cn("flex max-w-full min-w-0", className)}>
      {dir ? <span className="min-w-0 truncate">{dir}</span> : null}
      <ToolPathName name={base} />
    </span>
  )
}

/** A new file: the path in the header, then a file card with its name, size and first lines. */
export function ToolFileWrite({
  name = "write_file",
  path,
  content,
  overwrite = false,
  previewLines = 12,
  ...props
}: ToolFileWriteProps) {
  const running = isToolRunning(props.state, props.decision)
  const showBody =
    content !== undefined &&
    path !== undefined &&
    props.state !== "output-error" &&
    props.state !== "output-denied"
  const lines = content ? content.replace(/\n$/, "").split("\n").length : 0
  const bytes = content ? new TextEncoder().encode(content).length : 0
  const { dir, file } = splitPath(path ?? "")

  const body = showBody ? (
    <div
      data-slot="file-write-card"
      className="rounded-(--chatcn-radius-md) bg-(color:--chatcn-inset) min-w-0 overflow-hidden"
    >
      <div className="flex min-w-0 items-center gap-2 px-3 pt-2.5 pb-1">
        <FileCodeIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) size-4 shrink-0" />
        <span className="flex min-w-0 flex-1 items-baseline gap-1.5">
          <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) shrink-0 font-medium">{file}</span>
          {dir ? (
            <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) truncate font-mono">{dir}</span>
          ) : null}
        </span>
        <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
          {lines} {lines === 1 ? "line" : "lines"}, {formatBytes(bytes)}
        </span>
      </div>
      {content ? (
        <ToolCodePreview code={content} maxLines={previewLines} className="rounded-none" />
      ) : (
        <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) px-3 pb-2.5">Empty file</p>
      )}
    </div>
  ) : undefined

  const doneTitle = overwrite ? "Wrote" : "Created"
  return (
    <ToolCall
      name={name}
      icon={<FilePlus2Icon />}
      title={running ? "Writing" : props.state === "output-available" ? doneTitle : "Write"}
      detail={<ToolDetail>{path ? <ToolPath path={path} /> : undefined}</ToolDetail>}
      {...props}
    >
      {body}
    </ToolCall>
  )
}

/** True once a tool call will not change again. */
function isTerminalToolState(state: ToolDisplayState): boolean {
  return (
    state === "output-available" ||
    state === "output-error" ||
    state === "output-denied" ||
    state === "cancelled"
  )
}

/** Display state for a tool part; unfinished calls in a stopped response become `cancelled`. */
function getToolDisplayState(
  part: Pick<ChatcnToolPart, "state">,
  options?: { stopped?: boolean },
): ToolDisplayState {
  return options?.stopped && !isTerminalToolState(part.state) ? "cancelled" : part.state
}

/** Tool name for `tool-${name}` and `dynamic-tool` parts. */
function getToolName(part: Pick<ChatcnToolPart, "type" | "toolName">): string {
  if (part.type === "dynamic-tool") return part.toolName ?? ""
  return part.type.slice("tool-".length)
}

/* -------------------------------------------------------------------------------------------------
 * From a message part
 * -----------------------------------------------------------------------------------------------*/

/**
 * Maps a tool part (chatcn contract or AI SDK `UIMessage` part) to `ToolCall` props.
 * `<ToolCall {...toolCallPropsFromPart(part)} onApprove={...} />`
 */
function toolCallPropsFromPart(
  part: ChatcnToolPart,
  options?: { stopped?: boolean },
): Pick<
  ToolCallProps,
  "name" | "state" | "input" | "inputText" | "output" | "errorText" | "approval" | "decision"
> &
  Partial<Pick<ToolCallProps, "title">> {
  const state = getToolDisplayState(part, options)
  const approval = part.approval
  return {
    name: getToolName(part),
    ...(part.title ? { title: part.title } : {}),
    state,
    input: part.input,
    inputText: typeof part.rawInput === "string" ? part.rawInput : undefined,
    output: part.output,
    errorText: part.errorText,
    approval:
      approval && state === "approval-requested"
        ? { id: approval.id, reason: approval.requestReason }
        : undefined,
    decision:
      approval && approval.approved !== undefined
        ? { approved: approval.approved, reason: approval.reason }
        : undefined,
  }
}

/**
 * Lifecycle props from a tool part. A `preliminary` output (a tool still streaming its result)
 * keeps the call in its running state, so timers keep ticking and output keeps streaming.
 */
function toolBasePropsFromPart({
  part,
  stopped,
  variant,
  onApprove,
  onDeny,
  onRetry,
  durationMs,
  startedAt,
  open,
  defaultOpen,
  onOpenChange,
  className,
}: ToolRendererProps): ToolBaseProps {
  const { name, state, errorText, approval, decision } = toolCallPropsFromPart(part, { stopped })
  const preliminary = part.preliminary === true && state === "output-available"
  return {
    name,
    state: preliminary ? (stopped ? "cancelled" : "input-available") : state,
    errorText,
    approval,
    decision,
    variant,
    onApprove,
    onDeny,
    onRetry,
    durationMs,
    startedAt,
    open,
    defaultOpen,
    onOpenChange,
    className,
  }
}

/** Reads a record from unknown tool input or output. */
function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {}
}

/** First string value found under any of `keys`. */
function pickString(value: unknown, ...keys: string[]): string | undefined {
  const record = asRecord(value)
  for (const key of keys) {
    const v = record[key]
    if (typeof v === "string") return v
  }
  return undefined
}

export function ToolFileWritePart(props: ToolRendererProps) {
  const { part } = props
  return (
    <ToolFileWrite
      {...toolBasePropsFromPart(props)}
      path={pickString(part.input, "path", "file", "filePath", "file_path")}
      content={pickString(part.input, "content", "text", "contents")}
    />
  )
}

/** Tool names this renderer handles. Spread into your renderer map. */
export const toolFileWriteRenderers: ToolRendererMap = {
  write_file: ToolFileWritePart,
  write: ToolFileWritePart,
  create_file: ToolFileWritePart,
}

export default ToolFileWrite

